// NewLogsDecoder returns a streaming LogsDecoder that detects the CloudTrail log
// format and processes records incrementally.
//
// For the S3 Records format (a top-level "Records" array), the offset tracks the
// number of records processed. WithOffset skips that many records before decoding,
// and each DecodeLogs call returns up to WithFlushItems records.
//
// The CloudWatch subscription filter and digest formats are treated as a single
// logical unit: a non-zero offset causes the first DecodeLogs call to return io.EOF
// immediately, and the offset reflects the total number of bytes consumed.
func (u *CloudTrailLogUnmarshaler) NewLogsDecoder(reader io.Reader, options ...encoding.DecoderOption) (encoding.LogsDecoder, error) {
	opts := encoding.NewDecoderOptions(options...)

	bufferedReader := bufio.NewReaderSize(reader, readerBufferSize)

	// Peek into the first 64 bytes to determine the type of CloudTrail log
	peekBytes, err := bufferedReader.Peek(64)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("failed to peek into CloudTrail log: %w", err)
	}

	firstKey, err := extractFirstKey(peekBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to extract the first JSON key: %w", err)
	}

	// S3 CloudTrail log format (most common): a top-level "Records" array that
	// can be streamed record by record.
	if firstKey == "Records" {
		return u.newS3Decoder(bufferedReader, opts)
	}

	// CloudWatch subscription filter and digest formats represent a single JSON
	// value and are decoded as a whole. The byte offset is used to signal that the
	// value has already been consumed on a previous read.
	return u.newWholeValueDecoder(bufferedReader, firstKey, opts)
}

// newS3Decoder returns a LogsDecoder that streams records from a CloudTrail S3
// "Records" array. The offset is a record count.
func (u *CloudTrailLogUnmarshaler) newS3Decoder(reader *bufio.Reader, opts encoding.DecoderOptions) (encoding.LogsDecoder, error) {
	decoder := gojson.NewDecoder(reader)

	// Check opening bracket
	if token, err := decoder.Token(); err != nil || token != gojson.Delim('{') {
		return nil, fmt.Errorf("expected '{': %w", err)
	}

	// Move to Records array
	if _, err := decoder.Token(); err != nil {
		return nil, fmt.Errorf("expected 'Records' key: %w", err)
	}

	// Check for array opening
	if token, err := decoder.Token(); err != nil || token != gojson.Delim('[') {
		return nil, fmt.Errorf("expected '[': %w", err)
	}

	// The offset is the number of records processed so far. Skip records that
	// were already processed on a previous read.
	var offset int64
	for offset < opts.Offset && decoder.More() {
		var raw gojson.RawMessage
		if err := decoder.Decode(&raw); err != nil {
			return nil, fmt.Errorf("failed to skip CloudTrail record: %w", err)
		}
		offset++
	}

	decodeF := func() (plog.Logs, error) {
		logs, resourceLogs, scopeLogs := u.createLogs()
		logRecords := scopeLogs.LogRecords()

		var count int64
		init := true
		for decoder.More() {
			record := CloudTrailRecord{}
			if err := decoder.Decode(&record); err != nil {
				return plog.Logs{}, err
			}
			offset++

			if init {
				u.setResourceAttributes(resourceLogs.Resource().Attributes(), record)
				init = false
			}

			logRecord := logRecords.AppendEmpty()
			if err := u.setLogRecord(logRecord, &record); err != nil {
				return plog.Logs{}, err
			}

			count++
			if opts.FlushItems > 0 && count >= opts.FlushItems {
				return logs, nil
			}
		}

		if logRecords.Len() == 0 {
			return plog.NewLogs(), io.EOF
		}

		return logs, nil
	}

	return xstreamencoding.NewLogsDecoderAdapter(decodeF, func() int64 { return offset }), nil
}

// newWholeValueDecoder returns a LogsDecoder for CloudWatch subscription filter and
// digest formats, which are decoded as a single JSON value. The offset reflects the
// number of bytes consumed; a non-zero starting offset means the value was already
// consumed and DecodeLogs returns io.EOF immediately.
func (u *CloudTrailLogUnmarshaler) newWholeValueDecoder(reader *bufio.Reader, firstKey string, opts encoding.DecoderOptions) (encoding.LogsDecoder, error) {
	decoder := gojson.NewDecoder(reader)
	isCloudWatch := isCloudWatchKey(firstKey)

	offsetF := func() int64 { return decoder.InputOffset() }

	// A non-zero offset indicates the single value was already consumed on a
	// previous read. Discard it to advance the byte offset and signal EOF.
	if opts.Offset != 0 {
		var raw gojson.RawMessage
		if err := decoder.Decode(&raw); err != nil && !errors.Is(err, io.EOF) {
			return nil, fmt.Errorf("failed to skip consumed CloudTrail value: %w", err)
		}
		return xstreamencoding.NewLogsDecoderAdapter(
			func() (plog.Logs, error) { return plog.NewLogs(), io.EOF },
			offsetF,
		), nil
	}

	done := false
	decodeF := func() (plog.Logs, error) {
		if done {
			return plog.NewLogs(), io.EOF
		}
		done = true

		if isCloudWatch {
			return u.fromCloudWatchDecoder(decoder)
		}

		var cloudTrailDigest CloudTrailDigest
		if err := decoder.Decode(&cloudTrailDigest); err != nil {
			return plog.Logs{}, fmt.Errorf("failed to unmarshal payload as a CloudTrail digest: %w", err)
		}
		return u.processDigestRecord(cloudTrailDigest)
	}

	return xstreamencoding.NewLogsDecoderAdapter(decodeF, offsetF), nil
}

